import React, { useEffect, useState, useMemo } from 'react';
import { Target, Trophy, Plane, Home, TrendingUp, Plus, DollarSign, Laptop, Check, Star, XCircle, Wallet, Gift, AlertCircle, PieChart, Trash2, Calendar, Clock, AlertTriangle, Zap, Shield, Edit2 } from 'lucide-react';
import { Goal, Budget, Transaction, TransactionType, Category } from '../types';
import confetti from 'canvas-confetti';

interface GoalsProps {
  goals?: Goal[];
  budgets?: Budget[];
  transactions?: Transaction[];
  onAddGoal?: (goal: Goal) => void;
  onUpdateGoal?: (goal: Goal) => void;
  onAddBudget?: (budget: Budget) => void;
  onDeleteBudget?: (id: string) => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
}

const Goals: React.FC<GoalsProps> = ({ goals = [], budgets = [], transactions = [], onAddGoal, onUpdateGoal, onAddBudget, onDeleteBudget, formatCurrency }) => {
    const [isAddGoalModalOpen, setIsAddGoalModalOpen] = useState(false);
    const [isAddBudgetModalOpen, setIsAddBudgetModalOpen] = useState(false);
    const [selectedGoal, setSelectedGoal] = useState<Goal | null>(null);
    const [depositAmount, setDepositAmount] = useState('');
    const [streak, setStreak] = useState(0);

    // --- STREAK ALGORITHM (PRESERVED) ---
    useEffect(() => {
        const lastVisit = localStorage.getItem('nova_last_visit');
        const currentStreak = parseInt(localStorage.getItem('nova_streak') || '0');
        const today = new Date().toDateString();

        if (lastVisit !== today) {
            const yesterday = new Date();
            yesterday.setDate(yesterday.getDate() - 1);
            if (lastVisit === yesterday.toDateString()) {
                const newStreak = currentStreak + 1;
                setStreak(newStreak);
                localStorage.setItem('nova_streak', newStreak.toString());
            } else {
                setStreak(1);
                localStorage.setItem('nova_streak', '1');
            }
            localStorage.setItem('nova_last_visit', today);
        } else {
            setStreak(currentStreak || 1);
        }
    }, []);

    const handleDeposit = (e: React.FormEvent) => {
        e.preventDefault();
        if (!selectedGoal || !depositAmount) return;

        const amount = parseFloat(depositAmount);
        const newAmount = selectedGoal.currentAmount + amount;

        const updatedGoal = { ...selectedGoal, currentAmount: newAmount };
        if (onUpdateGoal) onUpdateGoal(updatedGoal);

        if (newAmount >= selectedGoal.targetAmount && selectedGoal.currentAmount < selectedGoal.targetAmount) {
             confetti({
                particleCount: 150,
                spread: 100,
                origin: { y: 0.6 },
                colors: ['#6366f1', '#ec4899', '#10b981', '#fbbf24']
            });
        }
        setSelectedGoal(null);
        setDepositAmount('');
    };

    // Aggregate Budget Stats for the Summary Header
    const budgetStats = useMemo(() => {
        const now = new Date();
        const currentMonth = now.getMonth();
        const currentYear = now.getFullYear();
        let totalLimit = 0;
        let totalSpent = 0;

        budgets.forEach(b => {
            totalLimit += b.limit;
            const spent = transactions
                .filter(t => 
                    t.category === b.category && 
                    t.type === TransactionType.EXPENSE && 
                    new Date(t.date).getMonth() === currentMonth &&
                    new Date(t.date).getFullYear() === currentYear
                )
                .reduce((acc, t) => acc + t.amount, 0);
            totalSpent += spent;
        });

        const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
        const daysLeft = daysInMonth - now.getDate();

        return { 
            totalLimit, 
            totalSpent, 
            percentage: totalLimit > 0 ? (totalSpent / totalLimit) * 100 : 0,
            daysLeft: Math.max(0, daysLeft)
        };
    }, [budgets, transactions]);

    // Aggregate Savings Stats
    const savingsStats = useMemo(() => {
        const totalTarget = goals.reduce((acc, g) => acc + g.targetAmount, 0);
        const totalSaved = goals.reduce((acc, g) => acc + g.currentAmount, 0);
        const percentage = totalTarget > 0 ? (totalSaved / totalTarget) * 100 : 0;
        return { totalTarget, totalSaved, percentage, count: goals.length };
    }, [goals]);

    return (
        <div className="space-y-8 animate-fade-in pb-10">
            {/* Header Section */}
            <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
                <div>
                    <h2 className="text-3xl font-black text-white tracking-tight flex items-center gap-3">
                        <Target className="w-8 h-8 text-indigo-500" />
                        Goals & Limits
                    </h2>
                    <p className="text-slate-400 mt-2 font-medium">Control your monthly burn rate and build wealth systematically.</p>
                </div>

                {/* Streak Badge - Compact & Modern */}
                <div className="bg-slate-900/80 border border-white/10 rounded-2xl p-2 pr-5 flex items-center gap-3 shadow-lg backdrop-blur-sm">
                    <div className="bg-gradient-to-br from-amber-400 to-orange-600 w-10 h-10 rounded-xl flex items-center justify-center text-white shadow-md">
                        <Zap className="w-5 h-5 fill-white animate-pulse" />
                    </div>
                    <div>
                        <div className="text-[9px] font-bold text-slate-500 uppercase tracking-widest leading-none mb-1">Current Streak</div>
                        <div className="text-xl font-black text-white leading-none">{streak} <span className="text-xs text-amber-500 font-bold">DAYS</span></div>
                    </div>
                </div>
            </div>

            {/* Split View Container */}
            <div className="grid grid-cols-1 xl:grid-cols-2 gap-8 items-start">

                {/* --- Left Column: Monthly Limits (Monarch Style) --- */}
                <div className="flex flex-col gap-6">

                    {/* Aggregate Summary Card */}
                    <div className="relative p-8 rounded-[2.5rem] bg-[#0f172a] border border-white/10 shadow-2xl overflow-hidden group">
                        <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-500/10 rounded-full blur-[80px] -mr-16 -mt-16 group-hover:bg-indigo-500/15 transition-colors"></div>

                        <div className="relative z-10">
                            <div className="flex justify-between items-start mb-6">
                                <div>
                                    <div className="flex items-center gap-2 mb-1">
                                        <div className="p-1.5 bg-indigo-500/20 rounded-lg text-indigo-400"><Shield className="w-4 h-4" /></div>
                                        <h3 className="text-sm font-bold text-slate-300">Monthly Limits</h3>
                                    </div>
                                    <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest pl-1">Total Category Caps</p>
                                </div>
                                <button 
                                    onClick={() => setIsAddBudgetModalOpen(true)} 
                                    className="p-2 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-xl border border-white/5 transition-all active:scale-95"
                                >
                                    <Plus className="w-5 h-5" />
                                </button>
                            </div>

                            <div className="flex items-baseline gap-2 mb-4">
                                <span className={`text-5xl font-black tracking-tighter ${budgetStats.totalSpent > budgetStats.totalLimit ? 'text-rose-500' : 'text-white'}`}>
                                    {formatCurrency(budgetStats.totalSpent)}
                                </span>
                                <span className="text-xl font-bold text-slate-500">
                                    / {formatCurrency(budgetStats.totalLimit)}
                                </span>
                            </div>

                            <div className="h-4 w-full bg-slate-800/50 rounded-full overflow-hidden mb-3 border border-white/5">
                                <div 
                                    className={`h-full rounded-full transition-all duration-1000 ${budgetStats.percentage > 100 ? 'bg-rose-500' : 'bg-gradient-to-r from-blue-500 to-indigo-500'}`} 
                                    style={{ width: `${Math.min(budgetStats.percentage, 100)}%` }}
                                ></div>
                            </div>

                            <div className="flex justify-between text-xs font-bold text-slate-400">
                                <span>{budgetStats.percentage.toFixed(0)}% Used</span>
                                <span>{budgetStats.daysLeft} Days Left</span>
                            </div>
                        </div>
                    </div>

