const CreditScoreGauge = ({ score, onNavigate }: { score: number, onNavigate: (tab: string) => void }) => {
    // If score is 0 or undefined, show "Set Score" state
    if (!score || score === 0) {
        return (
            <div className="flex flex-col items-center justify-center relative w-full h-full p-4 text-center">
                <div className="w-16 h-16 rounded-full bg-slate-800 border-2 border-dashed border-slate-600 flex items-center justify-center mb-3">
                    <Gauge className="w-8 h-8 text-slate-500" />
                </div>
                <h3 className="text-white font-bold text-sm mb-1">Score Not Set</h3>
                <p className="text-slate-500 text-[10px] mb-3 max-w-[120px]">Calibrate your credit score in settings to track health.</p>
                <button 
                    onClick={() => onNavigate('settings')}
                    className="px-4 py-2 bg-indigo-600 hover:bg-indigo-500 text-white text-[10px] font-bold uppercase tracking-widest rounded-lg transition-colors"
                >
                    Calibrate
                </button>
            </div>
        );
    }

    const max = 850;
    const min = 300;
    const range = max - min;
    const percentage = Math.min(Math.max((score - min) / range, 0), 1) * 100;

    // SVG Geometry for a 260-degree arc gauge
    const size = 160; 
    const strokeWidth = 12; 
    const center = size / 2;
    const radius = (size - strokeWidth) / 2 - 10;
    const startAngle = 140; // degrees
    const endAngle = 400; // degrees (140 + 260)
    const totalAngle = 260;

    const angleToRad = (angle: number) => (angle * Math.PI) / 180;

    const calculatePath = (percent: number) => {
        const start = angleToRad(startAngle);
        const end = angleToRad(startAngle + (percent / 100) * totalAngle);

        const x1 = center + radius * Math.cos(start);
        const y1 = center + radius * Math.sin(start);
        const x2 = center + radius * Math.cos(end);
        const y2 = center + radius * Math.sin(end);

        const largeArc = (percent / 100) * totalAngle > 180 ? 1 : 0;

        // If 0%, draw nothing to avoid artifact
        if (percent <= 0) return "";

        return `M ${x1} ${y1} A ${radius} ${radius} 0 ${largeArc} 1 ${x2} ${y2}`;
    };

    let statusText = 'Good';
    let statusColor = 'text-emerald-400';
    let statusBg = 'bg-emerald-500/10 border-emerald-500/20';

    if (score >= 800) { statusText = 'Excellent'; }
    else if (score >= 740) { statusText = 'Very Good'; }
    else if (score >= 670) { statusText = 'Good'; statusColor = 'text-blue-400'; statusBg = 'bg-blue-500/10 border-blue-500/20'; }
    else if (score >= 580) { statusText = 'Fair'; statusColor = 'text-amber-400'; statusBg = 'bg-amber-500/10 border-amber-500/20'; }
    else { statusText = 'Poor'; statusColor = 'text-rose-400'; statusBg = 'bg-rose-500/10 border-rose-500/20'; }

    return (
        <div className="flex flex-col items-center justify-center relative w-full h-full">
            <div className="relative w-36 h-36 flex items-center justify-center">
                <svg width="100%" height="100%" viewBox={`0 0 ${size} ${size}`}>
                    <defs>
                        <linearGradient id="gaugeGradient" x1="0%" y1="0%" x2="100%" y2="0%">
                            <stop offset="0%" stopColor="#ef4444" />
                            <stop offset="50%" stopColor="#f59e0b" />
                            <stop offset="100%" stopColor="#10b981" />
                        </linearGradient>
                        <filter id="glow" x="-20%" y="-20%" width="140%" height="140%">
                            <feGaussianBlur stdDeviation="4" result="blur" />
                            <feComposite in="SourceGraphic" in2="blur" operator="over" />
                        </filter>
                    </defs>
                    {/* Track */}
                    <path 
                        d={calculatePath(100)} 
                        fill="none" 
                        stroke="#1e293b" 
                        strokeWidth={strokeWidth} 
                        strokeLinecap="round" 
                    />
                    {/* Progress */}
                    <path 
                        d={calculatePath(percentage)} 
                        fill="none" 
                        stroke="url(#gaugeGradient)" 
                        strokeWidth={strokeWidth} 
                        strokeLinecap="round" 
                        filter="url(#glow)"
                        className="transition-all duration-1000 ease-out"
                    />
                </svg>

                <div className="absolute inset-0 flex flex-col items-center justify-center pt-4">
                    <span className="text-[10px] text-slate-500 font-bold uppercase tracking-widest mb-1">FICO</span>
                    <div className="text-4xl font-black text-white tracking-tighter leading-none">{score}</div>
                    <div className={`text-[9px] font-bold uppercase tracking-widest mt-2 px-2 py-0.5 rounded border ${statusColor} ${statusBg}`}>{statusText}</div>
                </div>
            </div>

            <div className="absolute -bottom-1 flex items-center gap-1 bg-slate-900/80 px-2 py-1 rounded-lg border border-white/5 shadow-lg backdrop-blur-sm">
                <span className="text-[8px] text-slate-400 font-bold uppercase">Updated Today</span>
            </div>
        </div>
    );
};

