                        {/* 1/4 Section (25%): Insight Ratio */}
                        <div className="lg:col-span-1 bg-slate-900/30 border-t lg:border-t-0 lg:border-l border-white/5 p-4 flex flex-col items-center justify-center text-center">
                             <div className="h-32 w-3 bg-slate-800 rounded-full relative overflow-hidden mb-4">
                                 <div 
                                    className={`absolute bottom-0 left-0 w-full rounded-full transition-all duration-1000 ${currentMonthRatio.ratio > 100 ? 'bg-rose-500' : 'bg-indigo-500'}`} 
                                    style={{ height: `${Math.min(currentMonthRatio.ratio, 100)}%` }}
                                 ></div>
                             </div>
                             <div className="text-2xl font-black text-white mb-2">{currentMonthRatio.ratio.toFixed(0)}%</div>
                             <p className="text-[9px] text-slate-500 font-bold uppercase tracking-wide text-center leading-relaxed">
                                You've spent {currentMonthRatio.ratio.toFixed(0)}% of your income.
                             </p>
                        </div>
                    </div>
                </div>

            </div>

            {/* RIGHT SIDEBAR */}
            <div className="lg:col-span-4 flex flex-col gap-6 h-full">

                {/* Goal Vector - Redesigned Grid */}
                <div className="glass-card p-6 rounded-[2.5rem] border border-white/5 bg-slate-900/40 flex flex-col gap-6">
                    {/* Header */}
                    <div className="flex justify-between items-center">
                        <div className="flex items-center gap-3">
                            <div className="w-10 h-10 rounded-full bg-rose-500/10 flex items-center justify-center border border-rose-500/20 shadow-[0_0_15px_rgba(244,63,94,0.2)]">
                                <Target className="w-5 h-5 text-rose-500" />
