        <circle 
          cx="16" 
          cy="16" 
          r={radius} 
          stroke={color} 
          strokeWidth="3" 
          fill="transparent" 
          strokeDasharray={circumference} 
          strokeDashoffset={strokeDashoffset} 
          strokeLinecap="round" 
        />
      </svg>
    </div>
  );
};

