  Eye, 
  EyeOff, 
  ShieldCheck, 
  Zap,
  Plus
} from 'lucide-react';

interface DashboardProps {
  accounts: Account[];
  transactions: Transaction[];
  goals: Goal[];
  budgets: Budget[];
  onNavigate: (tab: string, params?: any) => void;
  onAddTransaction: () => void;
  onAddGoal: () => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
  userPlan: UserPlan;
  onAskCoach: (query: string) => void;
  insightUsage: number;
  spendingStatus: SpendingStatus;
  currentPeriodSpend: number;
  spendingLimit: number;
  spendingPeriod: SpendingPeriod;
  userName: string;
  isPrivacyMode: boolean;
  onTogglePrivacy: () => void;
  creditScore: number;
}

const COLORS = ['#6366f1', '#ec4899', '#10b981', '#f59e0b', '#3b82f6', '#8b5cf6', '#06b6d4', '#f43f5e'];

const Dashboard: React.FC<DashboardProps> = ({
  accounts,
  transactions,
  goals,
  budgets,
  onNavigate,
  onAddTransaction,
  onAddGoal,
  formatCurrency,
  userPlan,
  onAskCoach,
  insightUsage,
  spendingStatus,
  currentPeriodSpend,
  spendingLimit,
  spendingPeriod,
  userName,
  isPrivacyMode,
  onTogglePrivacy,
  creditScore
}) => {

  const netWorth = useMemo(() => accounts.reduce((acc, curr) => acc + curr.balance, 0), [accounts]);

  const expenditureData = useMemo(() => {
    const now = new Date();
    const currentMonth = now.getMonth();
    const currentYear = now.getFullYear();

    const expenseTxs = transactions.filter(t => 
      t.type === TransactionType.EXPENSE && 
      new Date(t.date).getMonth() === currentMonth &&
      new Date(t.date).getFullYear() === currentYear
    );

    const total = expenseTxs.reduce((acc, t) => acc + t.amount, 0);
    const categoryMap: Record<string, number> = {};

    expenseTxs.forEach(t => {
      categoryMap[t.category] = (categoryMap[t.category] || 0) + t.amount;
    });

    const chartData = Object.entries(categoryMap)
      .map(([name, value]) => ({ name, value }))
      .sort((a, b) => b.value - a.value);

    return {
      total,
      chartData,
      topCategory: chartData.length > 0 ? chartData[0] : null,
      isEmpty: chartData.length === 0
    };
  }, [transactions]);

  return (
    <div className="space-y-6 animate-slide-up pb-20">
      {/* Header / Net Worth Card */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">

