                    <button onClick={onTogglePrivacy} className="text-slate-500 hover:text-white transition-colors">
                        {isPrivacyMode ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                    </button>
                </div>
                <div className="text-4xl md:text-5xl font-black text-white tracking-tighter mt-4">
                    {formatCurrency(netWorth)}
                </div>
            </div>
