                 </div>
                 <div className="mt-4 h-3 w-full bg-black/10 rounded-full overflow-hidden">
                     <div 
                        className={`h-full rounded-full transition-all duration-1000 ${spendingStatus.status === 'violation' ? 'bg-rose-500' : spendingStatus.status === 'warning' ? 'bg-amber-400' : 'bg-emerald-400'}`} 
                        style={{ width: `${Math.min(spendingStatus.ratio * 100, 100)}%` }}
