                >
                    <Target className="w-6 h-6 text-rose-400 group-hover:scale-110 transition-transform" />
                    <span className="text-[10px] font-black uppercase tracking-widest">Goals</span>
                </button>
            </div>
        </div>
      </div>

      {/* Main Content Area: Charts & Lists */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Spending Chart (2/3 width) */}
          <div className="lg:col-span-2">
                <div className="glass-card p-6 md:p-8 rounded-[2.5rem] border border-white/5 bg-[#0f172a]/60 backdrop-blur-xl relative overflow-hidden flex flex-col gap-6 min-h-[300px]">
                    <div className="flex justify-between items-start">
                        <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
                            <AlignLeft className="w-4 h-4 text-indigo-500" />
                            Spending chart
                        </h3>
                    </div>

                    <div className="flex flex-col md:flex-row items-start gap-8">
                        <div className="w-48 h-48 md:w-56 md:h-56 relative shrink-0 flex items-center justify-center">
                            {expenditureData.isEmpty ? (
                                <div className="text-center">
                                    <div className="w-40 h-40 rounded-full border-2 border-dashed border-indigo-500/30 flex items-center justify-center animate-pulse">
                                        <PieChartIcon className="w-10 h-10 text-indigo-500/50" />
                                    </div>
                                </div>
                            ) : (
                                <ResponsiveContainer width="100%" height="100%">
                                    <PieChart>
                                        <Pie
                                            data={expenditureData.chartData}
                                            cx="50%"
                                            cy="50%"
                                            innerRadius={60}
                                            outerRadius={90}
                                            paddingAngle={2}
                                            dataKey="value"
                                            stroke="none"
                                        >
                                            {expenditureData.chartData.map((entry, index) => (
                                                <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                            ))}
                                        </Pie>
                                        <Tooltip 
                                            contentStyle={{ backgroundColor: '#020617', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '12px', padding: '8px' }} 
                                            itemStyle={{ color: '#fff', fontSize: '12px', fontWeight: 'bold' }} 
                                            formatter={(v: number) => formatCurrency(v)} 
                                        />
                                    </PieChart>
                                </ResponsiveContainer>
                            )}
                        </div>

                        <div className="flex-1 w-full">
                            {expenditureData.topCategory ? (
                                <div className="mb-6 p-4 rounded-2xl bg-indigo-500/10 border border-indigo-500/20 flex items-center justify-between">
                                    <div>
                                        <span className="text-[10px] font-black text-indigo-400 uppercase tracking-widest block mb-1">Primary Drain</span>
                                        <span className="text-lg font-bold text-white">{expenditureData.topCategory.name}</span>
                                    </div>
                                    <div className="text-right">
                                        <span className="text-3xl font-black text-white block leading-none">{((expenditureData.topCategory.value / expenditureData.total) * 100).toFixed(0)}%</span>
                                        <span className="text-[10px] font-bold text-slate-400 block mt-1">{formatCurrency(expenditureData.topCategory.value)}</span>
                                    </div>
                                </div>
                            ) : (
                                <div className="mb-6 p-6 rounded-2xl bg-slate-900/50 border border-white/5 flex flex-col justify-center items-start text-left">
                                    <h4 className="text-white font-bold text-sm mb-1">Sensors Inactive</h4>
                                    <p className="text-slate-500 text-xs font-medium mb-3">Log expense data to initialize topology map.</p>
                                    <button onClick={onAddTransaction} className="text-indigo-400 font-bold text-xs uppercase tracking-widest hover:text-indigo-300 transition-colors flex items-center gap-1">
                                        Initialize <ChevronDown className="w-3 h-3 -rotate-90" />
                                    </button>
                                </div>
                            )}

                            <div className="space-y-3">
                                {!expenditureData.isEmpty && expenditureData.chartData.slice(0, 3).map((item, i) => (
                                    <div key={i} className="flex items-center justify-between group">
                                        <div className="flex items-center gap-3">
                                            <div className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: COLORS[i % COLORS.length] }}></div>
                                            <span className="text-xs font-bold text-slate-300 group-hover:text-white transition-colors">{item.name}</span>
                                        </div>
                                        <div className="h-1 flex-1 mx-4 bg-slate-800/50 rounded-full overflow-hidden">
                                            <div className="h-full rounded-full transition-all duration-1000" style={{ width: `${(item.value / expenditureData.total) * 60}%`, backgroundColor: COLORS[i % COLORS.length], opacity: 0.6 }}></div>
                                        </div>
                                        <span className="text-[10px] font-bold text-slate-500">MTD</span>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                </div>
          </div>

          {/* Recent Activity List (1/3 width) */}
          <div className="lg:col-span-1">
              <div className="glass-card p-6 md:p-8 rounded-[2.5rem] border border-white/5 bg-[#0f172a]/60 backdrop-blur-xl h-full flex flex-col">
                  <div className="flex justify-between items-center mb-6">
                      <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest">Recent Activity</h3>
                      <button onClick={() => onNavigate('transactions')} className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest hover:text-indigo-300">View All</button>
                  </div>

                  <div className="flex-1 overflow-y-auto custom-scrollbar space-y-3 pr-2 max-h-[300px] lg:max-h-none">
                      {transactions.length === 0 ? (
                          <div className="flex flex-col items-center justify-center h-full text-center opacity-50">
                              <p className="text-xs font-bold text-slate-500">No signals detected.</p>
                          </div>
                      ) : (
                          transactions.slice(0, 5).map(tx => (
                              <div key={tx.id} className="flex justify-between items-center p-3 rounded-xl hover:bg-white/5 transition-colors border border-transparent hover:border-white/5 group">
                                  <div className="flex items-center gap-3">
                                      <div className={`p-2 rounded-full ${tx.type === TransactionType.INCOME ? 'bg-emerald-500/10 text-emerald-400' : 'bg-rose-500/10 text-rose-400'}`}>
                                          {tx.type === TransactionType.INCOME ? <ArrowUpRight className="w-3 h-3" /> : <ArrowDownRight className="w-3 h-3" />}
                                      </div>
                                      <div>
                                          <div className="text-xs font-bold text-white truncate max-w-[100px]">{tx.merchant}</div>
                                          <div className="text-[9px] text-slate-500 uppercase font-bold tracking-wider">{tx.category}</div>
                                      </div>
                                  </div>
                                  <div className={`text-xs font-black ${tx.type === TransactionType.INCOME ? 'text-emerald-400' : 'text-slate-200'}`}>
                                      {tx.type === TransactionType.INCOME ? '+' : ''}{formatCurrency(tx.amount)}
                                  </div>
                              </div>
                          ))
                      )}
                  </div>
              </div>
          </div>
      </div>
    </div>
  );
};

export default Dashboard;
